using System;
using System.Drawing;
using System.IO;

namespace Fliqlo.Properties
{
    internal static class Resources
    {
        private static Bitmap _error;
        private static Bitmap _spinner;

        public static Bitmap error
        {
            get
            {
                if (_error == null)
                {
                    byte[] bytes = Convert.FromBase64String("");
                    using (MemoryStream ms = new MemoryStream(bytes))
                    {
                        _error = new Bitmap(ms);
                    }
                }
                return _error;
            }
        }

        public static Bitmap spinner
        {
            get
            {
                if (_spinner == null)
                {
                    byte[] bytes = Convert.FromBase64String("");
                    using (MemoryStream ms = new MemoryStream(bytes))
                    {
                        _spinner = new Bitmap(ms);
                    }
                }
                return _spinner;
            }
        }
    }
}
